const RAINBOW = ['#ff2d55', '#ff7a00', '#ffd60a', '#32d74b', '#00c7be', '#0a84ff', '#5e5ce6', '#bf5af2'];

// The looks. 'color' is the rainbow; 'high' black on white where the panel
// shows no color (every other ray black, nothing grey or see-through); 'inks'
// the rainbow in solid inks on color e-paper, where a blend or a tint
// dithers to confetti.
const LOOKS = {
  color: { colors: RAINBOW, flat: false, page: '', rim: '#fffaf0', dial: '#101827', dialRim: '', ink: '', hour: '#ffd60a', minute: '#64d2ff', second: '#ff375f', cap: '#ffffff', capDot: '#ff2d55', label: '#fffaf0', pill: '' },
  high: { colors: ['#000000'], flat: true, page: '#ffffff', rim: '#ffffff', dial: '#ffffff', dialRim: '#000000', ink: '#000000', hour: '#000000', minute: '#000000', second: '#000000', cap: '#000000', capDot: '#ffffff', label: '#000000', pill: '#ffffff' },
  inks: { colors: ['#ff0000', '#ffff00', '#008000', '#0000ff'], flat: true, page: '#000000', rim: '#ffffff', dial: '#000000', dialRim: '', ink: '#ffffff', hour: '#ffff00', minute: '#ffffff', second: '#ff0000', cap: '#ffffff', capDot: '#ff0000', label: '#ffffff', pill: '#000000' },
};

function lookOf(app: any) {
  const mode = app.state.contrast || 'auto';
  if (mode === 'high' || (mode === 'auto' && app.frame.color === false)) return LOOKS.high;
  if (mode === 'auto' && app.frame.paper === true) return LOOKS.inks;
  return LOOKS.color;
}

function fixed(n: number): number {
  return Math.round(n * 10) / 10;
}

export function get(app: any, context: any) {
  const W = Math.max(1, Math.round(context.targetWidth || context.imageWidth || app.frame.width || 1200));
  const H = Math.max(1, Math.round(context.targetHeight || context.imageHeight || app.frame.height || 1600));
  const cx = W / 2;
  const cy = H / 2;
  const S = Math.min(W, H);
  const look = lookOf(app);
  const COLORS = look.colors;
  // A flat look draws every other ray, ring or ribbon, in full ink.
  const skip = (i: number) => look.flat && i % 2 === 1;
  const full = app.state.clockFit === 'full';
  const style = app.state.rainbowStyle || 'prism';
  const showDigital = app.state.showDigitalClock !== false;
  const showWhiteOutline = app.state.showWhiteOutline !== false;
  // A round panel: a bigger dial with a ring of rainbow around it, and the
  // digital time inside the dial, over the 6 (below the dial is the rim).
  const round = context.round === true && !full;
  const r = round ? S * (showWhiteOutline ? 0.4 : 0.42) : S * (full ? (showWhiteOutline ? 0.455 : 0.49) : (showWhiteOutline ? 0.34 : 0.36));
  const outer = Math.sqrt(W * W + H * H);
  const d = new Date();
  const hr = d.getHours() % 12;
  const mn = d.getMinutes();
  const sc = d.getSeconds();
  const timeText = `${String(d.getHours()).padStart(2, '0')}:${String(mn).padStart(2, '0')}`;

  const hand = (angle: number, length: number, width: number, color: string) => {
    const a = angle - Math.PI / 2;
    return <line x1={cx} y1={cy} x2={fixed(cx + Math.cos(a) * length)} y2={fixed(cy + Math.sin(a) * length)} stroke={color} strokeWidth={fixed(width)} strokeLinecap="round" />;
  };

  // The time under the dial (never under 15 px on a flat look, where it sits on a plate).
  const timeY = fixed(cy + r * (full ? 0.73 : 1.33));
  const timeSize = look.flat ? Math.max(15, S * (full ? 0.042 : 0.055)) : S * (full ? 0.042 : 0.055);

  const background = look.page || (style === 'aurora' ? '#071a2a' : style === 'confetti' ? '#180d28' : style === 'ribbons' ? '#10142d' : style === 'spectrum' ? '#171126' : '#07111f');

  return (
    <svg viewBox={`0 0 ${W} ${H}`} width={W} height={H}>
      <defs>
        {COLORS.map((color, i) => {
          const a = (i / COLORS.length) * Math.PI * 2;
          return <linearGradient id={`g${i}`} gradientUnits="userSpaceOnUse" x1={cx} y1={cy} x2={fixed(cx + Math.cos(a) * W)} y2={fixed(cy + Math.sin(a) * H)}><stop offset="0" stopColor={color} stopOpacity="0.94" /><stop offset="1" stopColor={COLORS[(i + 1) % COLORS.length]} stopOpacity="0.5" /></linearGradient>;
        })}
        <radialGradient id="soft" gradientUnits="userSpaceOnUse" cx={cx} cy={cy} r={fixed(S * 0.72)}><stop offset="0" stopColor="#fff7d6" stopOpacity="0.62" /><stop offset="0.42" stopColor="#ffffff" stopOpacity="0.08" /><stop offset="1" stopColor={background} stopOpacity="0.26" /></radialGradient>
      </defs>
      <rect width={W} height={H} fill={background} />
      {style === 'prism' && Array.from({ length: 48 }, (_, i) => {
        const a1 = (i / 48) * Math.PI * 2;
        const a2 = ((i + 1.05) / 48) * Math.PI * 2;
        if (skip(i)) return null;
        const fill = look.flat ? COLORS[(i / 2) % COLORS.length] : `url(#g${i % COLORS.length})`;
        return (
          <path
            d={`M ${fixed(cx)} ${fixed(cy)} L ${fixed(cx + Math.cos(a1) * outer)} ${fixed(cy + Math.sin(a1) * outer)} L ${fixed(cx + Math.cos(a2) * outer)} ${fixed(cy + Math.sin(a2) * outer)} Z`}
            fill={fill}
            opacity={look.flat ? undefined : i % 2 ? 0.46 : 0.68}
          />
        );
      })}
      {style === 'aurora' && Array.from({ length: 12 }, (_, k) => skip(k) ? null : (
        <circle cx={cx} cy={cy} r={fixed(r * (1.18 + k * 0.16))} fill="none" stroke={COLORS[k % COLORS.length]}
          strokeWidth={fixed(S * 0.048)} opacity={look.flat ? undefined : 0.32} />
      ))}
      {style === 'ribbons' && Array.from({ length: 10 }, (_, i) => {
        const y = fixed(H * (0.08 + i * 0.095));
        const bend = fixed(S * (0.12 + (i % 3) * 0.04));
        if (skip(i)) return null;
        return (
          <path
            d={`M ${fixed(-S * 0.15)} ${y} C ${fixed(W * 0.26)} ${fixed(y - bend)}, ${fixed(W * 0.68)} ${fixed(y + bend)}, ${fixed(W + S * 0.15)} ${y}`}
            fill="none" stroke={COLORS[i % COLORS.length]} strokeWidth={fixed(S * 0.075)} strokeLinecap="round"
            opacity={look.flat ? undefined : '0.48'}
          />
        );
      })}
      {style === 'spectrum' && Array.from({ length: COLORS.length }, (_, i) => {
        const top = fixed((H / COLORS.length) * i);
        const band = H / COLORS.length;
        if (skip(i)) return null;
        return <path d={`M 0 ${top} L ${W} ${fixed(top - H * 0.12)} L ${W} ${fixed(top + band + H * 0.12)} L 0 ${fixed(top + band)} Z`} fill={COLORS[i]} opacity={look.flat ? undefined : '0.48'} />;
      })}
      {style === 'confetti' && Array.from({ length: 90 }, (_, i) => {
        const a = i * 2.39996;
        const distance = S * (0.12 + ((i * 37) % 100) / 100 * 0.7);
        const size = S * (0.012 + (i % 4) * 0.004);
        return <circle cx={fixed(cx + Math.cos(a) * distance)} cy={fixed(cy + Math.sin(a) * distance)} r={fixed(size)} fill={COLORS[i % COLORS.length]} opacity={look.flat ? undefined : '0.75'} />;
      })}
      {style !== 'none' && !look.flat && <rect width={W} height={H} fill="url(#soft)" />}
      {showWhiteOutline && (
        <circle cx={cx} cy={cy} r={fixed(r * 1.09)} fill={look.rim} opacity={look.flat ? undefined : '0.88'}
          stroke={look.dialRim || undefined} strokeWidth={look.dialRim ? Math.max(2, fixed(S * 0.006)) : undefined} />
      )}
      <circle cx={cx} cy={cy} r={fixed(r)} fill={look.dial} opacity={look.flat ? undefined : '0.93'}
        stroke={look.dialRim || undefined} strokeWidth={look.dialRim ? Math.max(2, fixed(S * 0.008)) : undefined} />
      {!look.flat && <circle cx={cx} cy={cy} r={fixed(r * 0.89)} fill="none" stroke="#ffffff" strokeWidth={fixed(S * 0.012)} opacity="0.18" />}
      {Array.from({ length: 60 }, (_, i) => {
        const a = (i / 60) * Math.PI * 2 - Math.PI / 2;
        const major = i % 5 === 0;
        const ro = r * 0.93;
        const ri = r * (major ? 0.78 : 0.84);
        const stroke = look.ink && !major ? look.ink : COLORS[Math.floor((i / 60) * COLORS.length) % COLORS.length];
        return (
          <line x1={fixed(cx + Math.cos(a) * ri)} y1={fixed(cy + Math.sin(a) * ri)} x2={fixed(cx + Math.cos(a) * ro)} y2={fixed(cy + Math.sin(a) * ro)}
            stroke={stroke} strokeWidth={Math.max(look.flat ? 1 : 0, fixed(S * (major ? 0.01 : 0.005)))} strokeLinecap="round"
            opacity={look.flat ? undefined : '0.98'} />
        );
      })}
      {Array.from({ length: 12 }, (_, i) => {
        const n = i + 1;
        const a = (n / 12) * Math.PI * 2 - Math.PI / 2;
        return <text x={fixed(cx + Math.cos(a) * r * 0.64)} y={fixed(cy + Math.sin(a) * r * 0.64)} textAnchor="middle" dominantBaseline="middle" fontFamily="Ubuntu" fontSize={fixed(S * 0.052)} fontWeight="700" fill={look.ink || COLORS[i % COLORS.length]}>{n}</text>;
      })}
      {hand(((hr + mn / 60) / 12) * Math.PI * 2, r * 0.42, S * 0.025, look.hour)}
      {hand(((mn + sc / 60) / 60) * Math.PI * 2, r * 0.62, S * 0.017, look.minute)}
      {hand((sc / 60) * Math.PI * 2, r * 0.72, Math.max(look.flat ? 1.5 : 0, S * 0.007), look.second)}
      <circle cx={cx} cy={cy} r={fixed(S * 0.034)} fill={look.cap} />
      <circle cx={cx} cy={cy} r={fixed(S * 0.02)} fill={look.capDot} />
      {showDigital && round && !look.flat && <rect x={fixed(cx - S * 0.075)} y={fixed(cy + r * 0.36 - S * 0.034)} width={fixed(S * 0.15)} height={fixed(S * 0.068)} rx={fixed(S * 0.034)} fill="#000000" opacity="0.35" />}
      {showDigital && round && <text x={cx} y={fixed(cy + r * 0.36 + S * 0.016)} textAnchor="middle" fontFamily="Ubuntu" fontSize={fixed(S * 0.046)} fontWeight="700" fill={look.flat ? look.ink : '#fffaf0'}>{timeText}</text>}
      {/* Under the dial the time sits on the rays: on a flat look, on a plate of its own. */}
      {showDigital && !round && look.pill && (
        <rect x={fixed(cx - timeSize * 1.75)} y={fixed(timeY - timeSize * 1.05)} width={fixed(timeSize * 3.5)} height={fixed(timeSize * 1.45)}
          rx={fixed(timeSize * 0.3)} fill={look.pill} stroke={look.label} strokeWidth={2} />
      )}
      {showDigital && !round && (
        <text x={cx} y={timeY} textAnchor="middle" fontFamily="Ubuntu" fontSize={fixed(timeSize)} fontWeight="700" fill={look.label}>{timeText}</text>
      )}
    </svg>
  );
}
